// main.js — shared: data, image slots, contact fields, menu, booking sheet, forms, reveal, counters
// Language: Arabic pages at the root, French in fr/, English in en/ (generated by tools/build_i18n.py)
export const LANG = ['fr', 'en'].includes(document.documentElement.lang) ? document.documentElement.lang : 'ar';
export const FR = LANG === 'fr', EN = LANG === 'en', LTR = LANG !== 'ar';
export const BASE = LTR ? '../' : '';
export const tt = (ar, fr, en) => (EN ? en : FR ? fr : ar);
// Keyboard: next/previous follow the reading direction (← is next in Arabic, → in French and English)
export const step = k => ({ ArrowLeft: LTR ? -1 : 1, ArrowRight: LTR ? 1 : -1 })[k];
const cache = {};
const DV = '?v=a8a05a68'; // data version, written by tools/stamp.py: a changed JSON is never served from an old cache
export const json = p => (cache[p] ||= fetch(BASE + (LTR ? p.replace('data/', `data/${LANG}/`) : p) + DV).then(r => (r.ok ? r.json() : Promise.reject(p))));
export const $ = (s, r = document) => r.querySelector(s);
export const $$ = (s, r = document) => [...r.querySelectorAll(s)];
export const esc = s => String(s ?? '').replace(/[&<>"]/g, c => `&#${c.charCodeAt(0)};`);
export const icon = n => `<svg class="i" aria-hidden="true"><use href="${BASE}img/icons.svg#${n}"/></svg>`;
// 20700 → «20 700» with a narrow no-break space (bidi class CS: «20 700» stays one number); in Arabic the number is also
// isolated left-to-right (U+2066…U+2069) so an RTL line can never show it as «700 20»
const thin = n => n.toLocaleString('fr-FR').replace(/\s/g, ' ');
export const fmt = n => (EN ? n.toLocaleString('en-US') : LTR ? thin(n) : `⁦${thin(n)}⁩`);
export const ASK = `<span class="tbd">${tt('عند الطلب', 'Sur demande', 'On request')}</span>`;
export const ROOT = 'https://chekhabayoub04-glitch.github.io/new-vession-promition-/' + (LTR ? `${LANG}/` : '');
const SITE = 'https://chekhabayoub04-glitch.github.io/new-vession-promition-/';
export const ld = o => document.head.insertAdjacentHTML('beforeend', `<script type="application/ld+json">${JSON.stringify(o)}</script>`);
export const day = () => new Date().toISOString().slice(0, 10);
export const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
export let site = {};
let IMG = {};
export const ready = Promise.all([json('data/site.json'), json('data/images.json').catch(() => ({}))]).then(([s, i]) => ((IMG = i), (site = s)));

// Listed slot → AVIF/WebP/JPEG; else the arch placeholder naming the file
export function pic(slot, alt = '', sizes = '100vw', eager) {
  const m = IMG[slot];
  if (!m) return `<span class="ph" ${alt ? `role="img" aria-label="${esc(alt)}"` : 'aria-hidden="true"'}><span>img/${slot}.avif</span></span>`;
  const set = f => m.widths.map(w => `${BASE}img/${slot}-${w}.${f} ${w}w`).join();
  return `<picture><source type="image/avif" srcset="${set('avif')}" sizes="${sizes}"><source type="image/webp" srcset="${set('webp')}" sizes="${sizes}"><img src="${BASE}img/${slot}-${m.widths.at(-1)}.jpg" srcset="${set('jpg')}" sizes="${sizes}" width="${m.w}" height="${m.h}" alt="${esc(alt)}" ${eager ? 'fetchpriority="high"' : 'loading="lazy"'} decoding="async"></picture>`;
}
export const hasImg = s => !!IMG[s];
export const roomName = (r, i) => r.name || tt(`نوع الغرفة ${i + 1}`, `Catégorie ${i + 1}`, `Room type ${i + 1}`);
// 14:00 → «14:00» in Arabic, «14h00» in French, «2:00 pm» in English
const hm = v => { const [h, m] = v.split(':').map(Number), mm = String(m).padStart(2, '0'); return EN ? `${h % 12 || 12}:${mm} ${h < 12 ? 'am' : 'pm'}` : FR ? `${h}h${mm}` : v; };
function fillSite(s) {
  const link = (el, href, text) => (href ? ((el.href = href), (el.textContent = text)) : (el.removeAttribute('href'), (el.innerHTML = ASK)));
  const mail = (el, m) => (m ? ((el.href = `mailto:${m}`), (el.innerHTML = esc(m).replace('@', '<wbr>@').replace(/^([^@.]+\.)/, '$1<wbr>'))) : (el.removeAttribute('href'), (el.innerHTML = ASK))); // breaks only before «@» (and after the first «.» of the name part)
  for (const el of $$('[data-site]')) {
    const k = el.dataset.site;
    if (k === 'phone') link(el, s.phoneE164 && `tel:${s.phoneE164}`, s.phoneDisplay || s.phoneE164);
    else if (k === 'email') mail(el, s.email);
    else if (k === 'booking-email') mail(el, s.bookingEmail);
    else if (k === 'call') s.phoneE164 && (el.href = `tel:${s.phoneE164}`);
    else if (k === 'fax') el.textContent = s.faxDisplay || ASK;
    else if (k === 'reviews') el.href = s.reviewsUrl;
    else if (k === 'address') el.textContent = [s.streetAddress, s.region].filter(Boolean).join(tt('، ', ', ', ', '));
    else if (k === 'year') el.textContent = new Date().getFullYear();
    else if (k === 'checkin' || k === 'checkout') s[k] && (el.innerHTML = (el.hasAttribute('data-bare') ? '' : k === 'checkin' ? tt('من ', 'dès ', 'from ') : tt('حتى ', 'jusqu\'à ', 'until ')) + `<time datetime="${s[k]}">${hm(s[k])}</time>`);
    else if (s[k]) el.textContent = s[k];
  }
}

// Reveal once, 40 ms stagger (max 6); counters: real stats only.
// Rows that scroll sideways (.strip, .cards, .rail) are watched as a whole: their off-screen items are clipped by the
// row, so watched one by one they would stay invisible until swiped to — the whole row appears together instead.
// A fast fling can carry an element from below the screen to above it between two frames. The watched area therefore
// reaches far above the screen (10 000 px): anything the visitor has scrolled past counts as seen and shows at once —
// computed by the browser off the main thread, no per-frame layout reads (those cost 40–70 ms on mid-range phones).
const SIDEWAYS = '.strip, .cards, .rail';
const show = t => { io.unobserve(t); (t.matches('.reveal') ? [t] : $$('.reveal:not(.in)', t)).forEach(el => (el.classList.add('in'), count(el))); };
const io = !reduced && new IntersectionObserver(es => es.forEach(e => e.isIntersecting && show(e.target)), { rootMargin: '10000px 0px -10% 0px' });
export function reveal(root = document) {
  const n = new Map();
  for (const el of $$('.reveal:not(.in)', root)) {
    const k = n.get(el.parentElement) || 0;
    n.set(el.parentElement, k + 1);
    el.style.setProperty('--stagger', `${Math.min(k, 5) * 40}ms`);
    if (!io) { el.classList.add('in'); count(el); continue; }
    io.observe(el.parentElement.matches(SIDEWAYS) ? el.parentElement : el);
  }
}
function count(el) {
  for (const b of $$('[data-stat]', el.parentElement)) {
    const v = site.stats?.[b.dataset.stat];
    if (v == null) { b.closest('.stat').hidden = true; continue; }
    const t0 = performance.now(), step = t => { const k = reduced ? 1 : Math.min(1, (t - t0) / 280); b.textContent = Math.round(v * (1 - (1 - k) ** 4)); k < 1 && requestAnimationFrame(step); };
    requestAnimationFrame(step);
  }
}

// Language switch keeps the same room / anchor (room.html?id=… → fr/room.html?id=…)
$$('[data-lang]').forEach(a => (a.href += location.search + location.hash));
addEventListener('click', e => $$('.lang-m[open]').forEach(d => d.contains(e.target) || (d.open = false)));
addEventListener('keydown', e => e.key === 'Escape' && $$('.lang-m[open]').forEach(d => ((d.open = false), $('summary', d).focus())));

// Night mode: follows the phone (prefers-color-scheme) until the visitor picks one; the pick is saved (hy-theme).
// The <head> script applies it before the first paint (no white flash); the switch is one View Transition crossfade.
const root = document.documentElement, night = matchMedia('(prefers-color-scheme: dark)');
const isDark = () => (root.dataset.theme || (night.matches ? 'dark' : 'light')) === 'dark';
const paintTheme = () => {
  const dark = isDark();
  $$('[data-theme-toggle]').forEach(b => { b.setAttribute('aria-pressed', dark); b.setAttribute('aria-label', dark ? tt('الوضع النهاري', 'Mode jour', 'Light mode') : tt('الوضع الليلي', 'Mode nuit', 'Dark mode')); });
  $$('meta[name="theme-color"]').forEach(m => (m.content = root.dataset.theme ? (dark ? '#0E0C09' : '#FCFAF6') : m.media.includes('dark') ? '#0E0C09' : '#FCFAF6'));
};
addEventListener('click', e => {
  if (!e.target.closest('[data-theme-toggle]')) return;
  const next = isDark() ? 'light' : 'dark';
  const apply = () => { root.dataset.theme = next; try { localStorage.setItem('hy-theme', next); } catch {} paintTheme(); };
  if (!document.startViewTransition || reduced) return apply();
  const vt = document.startViewTransition(apply); // a second tap before the crossfade ends skips the first one: not an error
  vt.ready.catch(() => {}); vt.finished.catch(() => {});
});
night.addEventListener('change', paintTheme);
paintTheme();

const menu = $('.menu-btn'), setMenu = o => (document.body.classList.toggle('nav-open', o), menu.setAttribute('aria-expanded', o));
menu.onclick = () => setMenu(!document.body.classList.contains('nav-open'));
$('.nav').onclick = e => e.target.closest('a') && setMenu(false);
addEventListener('keydown', e => e.key === 'Escape' && setMenu(false));

$$('dialog').forEach(d => d.addEventListener('close', () => d.from?.focus()));
addEventListener('click', e => e.target.closest('[data-close]')?.closest('dialog').close());

// Footer documents (house guide, certificate): a thumbnail button opens the page in a dialog that scrolls,
// with a link to the full-size file (pinch-zoom on phones); each button shows only once its photo exists
function docs() {
  $$('[data-doc]').forEach(b => {
    const slot = b.dataset.doc;
    if (!hasImg(slot)) return;
    b.hidden = false;
    $('.doc-thumb', b)?.insertAdjacentHTML('beforeend', pic(slot, '', '48px'));
    b.onclick = () => {
      let d = $(`#doc-${slot}`);
      if (!d) {
        const full = `${BASE}img/${slot}-${IMG[slot].widths.at(-1)}.jpg`, note = b.dataset.note ? `<small>${esc(b.dataset.note)}</small>` : '';
        document.body.insertAdjacentHTML('beforeend', `<dialog class="doc-dlg" id="doc-${slot}" aria-labelledby="doc-${slot}-h"><div class="dlg-head"><h2 id="doc-${slot}-h">${esc(b.dataset.title)}</h2><button type="button" class="icon-btn" data-close aria-label="${tt('إغلاق', 'Fermer', 'Close')}">${icon('x')}</button></div><div class="doc-img" tabindex="0" role="region" aria-label="${esc(b.dataset.title)}">${pic(slot, b.dataset.alt, '(min-width: 800px) 760px, 100vw')}</div><div class="doc-foot">${note}<a href="${full}" target="_blank" rel="noopener">${icon('zoom-in')}${tt('فتح بالحجم الكامل', 'Ouvrir en taille réelle', 'Open full size')}</a></div></dialog>`);
        d = $(`#doc-${slot}`);
        d.addEventListener('close', () => d.from?.focus());
        d.onclick = e => e.target === d && d.close();
      }
      d.from = b;
      d.showModal();
      $('.doc-img', d).scrollTop = 0;
    };
  });
}

ready.then(s => {
  fillSite(s);
  docs();
  $$('[data-slot]').forEach(el => $('picture', el) || (el.innerHTML = pic(el.dataset.slot, el.dataset.alt, el.dataset.sizes)));
  reveal();
}, () => reveal());
